using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table: reversed bits for each byte value 0–255.
    private static readonly byte[] LookupTable = CreateLookupTable();

    private static byte[] CreateLookupTable()
    {
        var table = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            int b = i;
            b = ((b & 0xF0) >> 4) | ((b & 0x0F) << 4);
            b = ((b & 0xCC) >> 2) | ((b & 0x33) << 2);
            b = ((b & 0xAA) >> 1) | ((b & 0x55) << 1);
            table[i] = (byte)b;
        }
        return table;
    }

    // Nibble reverse lookup: index 0–15 maps to the bit-reversed nibble shifted to high 4 bits.
    private static ReadOnlySpan<byte> NibbleReverseLow => [0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E, 0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F];
    private static ReadOnlySpan<byte> NibbleReverseHigh => [0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0, 0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0];

    public static void ReverseInPlace(Span<byte> data)
    {
        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int length = data.Length;
        int i = 0;

        if (Avx2.IsSupported && length >= 32)
        {
            var lowNibbleMask = Vector256.Create((byte)0x0F);
            var lut_lo = Vector256.Create(NibbleReverseLow).WithUpper(Vector128.Create(NibbleReverseLow));
            var lut_hi = Vector256.Create(NibbleReverseHigh).WithUpper(Vector128.Create(NibbleReverseHigh));

            for (; i + 32 <= length; i += 32)
            {
                ref byte src = ref Unsafe.Add(ref ptr, i);
                var vec = Unsafe.As<byte, Vector256<byte>>(ref src);

                var lo = Avx2.And(vec, lowNibbleMask);
                var hi = Avx2.And(Avx2.ShiftRightLogical(vec.AsUInt16(), 4).AsByte(), lowNibbleMask);

                var reversedLo = Avx2.Shuffle(lut_hi, lo);
                var reversedHi = Avx2.Shuffle(lut_lo, hi);

                var result = Avx2.Or(reversedLo, reversedHi);
                Unsafe.As<byte, Vector256<byte>>(ref src) = result;
            }
        }
        else if (Ssse3.IsSupported && length >= 16)
        {
            var lowNibbleMask = Vector128.Create((byte)0x0F);
            var lut_lo = Vector128.Create(NibbleReverseLow);
            var lut_hi = Vector128.Create(NibbleReverseHigh);

            for (; i + 16 <= length; i += 16)
            {
                ref byte src = ref Unsafe.Add(ref ptr, i);
                var vec = Unsafe.As<byte, Vector128<byte>>(ref src);

                var lo = Sse2.And(vec, lowNibbleMask);
                var hi = Sse2.And(Sse2.ShiftRightLogical(vec.AsUInt16(), 4).AsByte(), lowNibbleMask);

                var reversedLo = Ssse3.Shuffle(lut_hi, lo);
                var reversedHi = Ssse3.Shuffle(lut_lo, hi);

                var result = Sse2.Or(reversedLo, reversedHi);
                Unsafe.As<byte, Vector128<byte>>(ref src) = result;
            }
        }
        else if (AdvSimd.IsSupported && length >= 16)
        {
            var lowNibbleMask = Vector128.Create((byte)0x0F);
            var lut_lo = Vector128.Create(NibbleReverseLow);
            var lut_hi = Vector128.Create(NibbleReverseHigh);

            for (; i + 16 <= length; i += 16)
            {
                ref byte src = ref Unsafe.Add(ref ptr, i);
                var vec = Unsafe.As<byte, Vector128<byte>>(ref src);

                var lo = AdvSimd.And(vec, lowNibbleMask);
                var hi = AdvSimd.And(AdvSimd.ShiftRightLogical(vec.AsUInt16(), 4).AsByte(), lowNibbleMask);

                var reversedLo = AdvSimd.Arm64.VectorTableLookup(lut_hi, lo);
                var reversedHi = AdvSimd.Arm64.VectorTableLookup(lut_lo, hi);

                var result = AdvSimd.Or(reversedLo, reversedHi);
                Unsafe.As<byte, Vector128<byte>>(ref src) = result;
            }
        }

        // Scalar tail using lookup table
        byte[] table = LookupTable;
        for (; i < length; i++)
        {
            Unsafe.Add(ref ptr, i) = table[Unsafe.Add(ref ptr, i)];
        }
    }
}

